export const ART_IDS = Object.keys(ART);
export const artByCategory = (category) => ART_IDS.filter((id) => ART[id].category === category);
// Returns the entry for an id, or null when the picture is not shipped (callers keep their code-drawn fallback).
export const art = (id) => ART[id] || null;
// Time of day: 'day' or 'dawn' returns the '<id>-day' picture when one exists, otherwise (and for 'night') the plain id; null if neither is shipped.
export const artFor = (id, time) => ((time === 'day' || time === 'dawn') && ART[`${id}-day`]) || ART[id] || null;
